schema.content:
Table "Campuses" {
  "Id" INTEGER [pk]
  "Campus" TEXT
  "Location" TEXT
  "County" TEXT
  "Year" INTEGER
}

Table "csu_fees" {
  "Campus" INTEGER [pk]
  "Year" INTEGER
  "CampusFee" INTEGER
}

Table "degrees" {
  "Year" INTEGER [pk]
  "Campus" INTEGER [pk]
  "Degrees" INTEGER
}

Table "discipline_enrollments" {
  "Campus" INTEGER [pk]
  "Discipline" INTEGER [pk]
  "Year" INTEGER
  "Undergraduate" INTEGER
  "Graduate" INTEGER
}

Table "enrollments" {
  "Campus" INTEGER [pk]
  "Year" INTEGER [pk]
  "TotalEnrollment_AY" INTEGER
  "FTE_AY" INTEGER
}

Table "faculty" {
  "Campus" INTEGER
  "Year" INTEGER
  "Faculty" REAL
}



Ref: "csu_fees"."Campus" > "Campuses"."Id"

Ref: "degrees"."Campus" > "Campuses"."Id"

Ref: "discipline_enrollments"."Campus" > "Campuses"."Id"

Ref: "enrollments"."Campus" > "Campuses"."Id"

Ref: "faculty"."Campus" > "Campuses"."Id"
